/* VCD dumping routines */

unsigned int MOD_module_control::dump_VCD_defs(unsigned int levels)
{
  vcd_write_scope_start(sim_hdl, inst_name);
  vcd_num = vcd_reserve_ids(sim_hdl, 4u);
  unsigned int num = vcd_num;
  for (unsigned int clk = 0u; clk < bk_num_clocks(sim_hdl); ++clk)
    vcd_add_clock_def(sim_hdl, this, bk_clock_name(sim_hdl, clk), bk_clock_vcd_num(sim_hdl, clk));
  vcd_write_def(sim_hdl, num++, "CAN_FIRE_control", 1u);
  vcd_write_def(sim_hdl, num++, "RDY_control", 1u);
  vcd_write_def(sim_hdl, num++, "control", 31u);
  vcd_write_def(sim_hdl, num++, "control_d", 76u);
  vcd_write_scope_end(sim_hdl);
  return num;
}

void MOD_module_control::dump_VCD(tVCDDumpType dt, unsigned int levels, MOD_module_control &backing)
{
  vcd_defs(dt, backing);
}

void MOD_module_control::vcd_defs(tVCDDumpType dt, MOD_module_control &backing)
{
  unsigned int num = vcd_num;
  if (dt == VCD_DUMP_XS)
  {
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 31u);
    vcd_write_x(sim_hdl, num++, 76u);
  }
  else
    if (dt == VCD_DUMP_CHANGES)
    {
      if ((backing.DEF_CAN_FIRE_control) != DEF_CAN_FIRE_control)
      {
	vcd_write_val(sim_hdl, num, DEF_CAN_FIRE_control, 1u);
	backing.DEF_CAN_FIRE_control = DEF_CAN_FIRE_control;
      }
      ++num;
      if ((backing.PORT_RDY_control) != PORT_RDY_control)
      {
	vcd_write_val(sim_hdl, num, PORT_RDY_control, 1u);
	backing.PORT_RDY_control = PORT_RDY_control;
      }
      ++num;
      if ((backing.PORT_control) != PORT_control)
      {
	vcd_write_val(sim_hdl, num, PORT_control, 31u);
	backing.PORT_control = PORT_control;
      }
      ++num;
      if ((backing.PORT_control_d) != PORT_control_d)
      {
	vcd_write_val(sim_hdl, num, PORT_control_d, 76u);
	backing.PORT_control_d = PORT_control_d;
      }
      ++num;
    }
    else
    {
      vcd_write_val(sim_hdl, num++, DEF_CAN_FIRE_control, 1u);
      backing.DEF_CAN_FIRE_control = DEF_CAN_FIRE_control;
      vcd_write_val(sim_hdl, num++, PORT_RDY_control, 1u);
      backing.PORT_RDY_control = PORT_RDY_control;
      vcd_write_val(sim_hdl, num++, PORT_control, 31u);
      backing.PORT_control = PORT_control;
      vcd_write_val(sim_hdl, num++, PORT_control_d, 76u);
      backing.PORT_control_d = PORT_control_d;
    }
}
